--[=[
	@class IHostingEnvironment
	主机环境
]=]

export type IHostingEnvironment = {
	--[=[
		@prop EnvironmentName string
		@within IHostingEnvironment
		@readonly
		环境名称
	]=]
	EnvironmentName: string,

	--[=[
		@prop ApplicationName string
		@within IHostingEnvironment
		@readonly
		应用名称
	]=]
	ApplicationName: string,

	--[=[
		@prop ContentRootPath string
		@within IHostingEnvironment
		@readonly
		根节点路径
	]=]
	ContentRootPath: string,

	--[=[
		@prop LuaTypeProvider ILuaTypeProvider
		@within IHostingEnvironment
		@readonly
		LuaType提供者
	]=]
	LuaTypeProvider: ILuaTypeProvider,

	--[=[
		@prop Context string
		@within IHostingEnvironment
		@readonly
		上下文
	]=]
	Context: string,

	--[=[
		当前上下文是否在指定上下文中

		比如当前上下文为Server, 则 IsInContext("Server") 返回true, IsInContext("Client") 返回false
		
		@param context -- 如果参数为空, 则表示当前业务同时符合客户端或者服务端上下文
	]=]
	MatchContext: (context: "Server" | "Client" | nil | "") -> boolean,

	--- 是否为 Studio
	IsStudio: () -> boolean,

	--- 是否为 Server
	IsServer: () -> boolean,

	--- 是否为 Client
	IsClient: () -> boolean,

	--- 更新属性
	UpdateProperty: (self: IHostingEnvironment, name: string, value: any) -> ()
}

return {}
